INSERT INTO products (slug, name, category, description, material, price, price_min, price_max, image_url, in_stock) VALUES
  ('churrasqueira-rotativa-9', 'Churrasqueira Rotativa 9 Espetos', 'churrasqueira', 'Sistema rotativo motorizado com 9 espetos simultaneos e grelha auxiliar em aco inox AISI 304. Motor de baixa rotacao garante assamento uniforme sem ressecamento. Estrutura em aco carbono pintado a po. Preco 30% abaixo da concorrencia premium.', 'Aco carbono + inox AISI 304 + motor eletrico 12V', 4500, 4500, 4500, 'https://cdn.awsli.com.br/2500x2500/1741/1741826/produto/277373056/faze-uhg16vxuzl.png', 1),
  ('capo-celeron', 'Capo com Celeron', 'churrasqueira', 'Tampa para churrasqueira com camada de Celeron (polimero de alta performance, isolamento ate 120C) e revestimento interno em tijolo refratario. Mantém o calor interno e protege o operador. Protecao que voce sente no toque.', 'Aco carbono + Celeron + tijolo refratario', 0, 0, 0, 'https://cdn.awsli.com.br/2500x2500/1741/1741826/produto/277449876/imperial-l2bht2bt14.png', 0),
  ('grelha-inox-grande', 'Grelha Inox 60x40cm', 'grelha', 'Grelha em aco inox AISI 304 nas dimensoes 60x40cm. Barras de 6mm com acabamento polido. Resistente a corrosao e facil higienizacao. Compativel com churrasqueiras de alvenaria e churrasqueiras pre-fabricadas.', 'Inox AISI 304', 280, 250, 320, 'https://images.tcdn.com.br/img/img_prod/1414367/churrasqueira_grill_rotativa_the_grill_inox_5_es_1_20250724093144_17b805060c0c.jpg', 1),
  ('espeto-duplo', 'Espeto Duplo Inox', 'espeto', 'Espeto duplo em aco inox AISI 304 com ponta polida a 15 graus. Dois vergalhoes paralelos de 8mm garantem firmeza extra para carnes maiores como picanha e costela. Comprimento 70cm, cabo com ponteira quadrada para suporte.', 'Inox AISI 304', 35, 25, 45, 'https://cdn.sistemawbuy.com.br/arquivos/100c580baca8c725f35897c2510dbb91/produtos/MO6DA4/735d68c44e1fc161aed24fc7a78c60c0-6691833bd2395.jpg', 1),
  ('espeto-em-v', 'Espeto em V Inox', 'espeto', 'Espeto em formato V em aco inox AISI 304. Abertura calibrada para frango inteiro, coracoes e carnes que tendem a girar no espeto convencional. Comprimento 70cm, acabamento polido.', 'Inox AISI 304', 40, 30, 50, 'https://cdn.sistemawbuy.com.br/arquivos/100c580baca8c725f35897c2510dbb91/produtos/MO6DA4/735d68c44e1fc161aed24fc7a78c60c0-6691833bd2395.jpg', 1),
  ('espeto-tridente', 'Espeto Tridente Inox', 'espeto', 'Espeto tridente em aco inox AISI 304 com tres pontas convergentes. Excelente para linguica, queijo coalho, legumes e carnes menores que exigem suporte multiponto. Comprimento 70cm.', 'Inox AISI 304', 45, 35, 55, 'https://cdn.sistemawbuy.com.br/arquivos/100c580baca8c725f35897c2510dbb91/produtos/MO6DA4/735d68c44e1fc161aed24fc7a78c60c0-6691833bd2395.jpg', 1);
